N, M, P = 2, 3, 10
NM, MP, PN = N * M, M * P, P * N

def u_idx(i, j): return i * M + j
def v_idx(j, k): return j * P + k
def w_idx(k, i): return k * N + i

def _verify(U, V, W, tol=1e-8):
    Ua = np.array(U, dtype=float); Va = np.array(V, dtype=float); Wa = np.array(W, dtype=float)
    for i in range(N):
        for j in range(M):
            for k in range(P):
                s = np.dot(Ua[u_idx(i, j)], Va[v_idx(j, k)] * Wa[w_idx(k, i)])
                if abs(s - 1.0) > tol:
                    return False
    return True

def _schoolbook():
    R = N * M * P
    U = np.zeros((NM, R)); V = np.zeros((MP, R)); W = np.zeros((PN, R))
    col = 0
    for i in range(N):
        for j in range(M):
            for k in range(P):
                U[u_idx(i, j), col] = 1
                V[v_idx(j, k), col] = 1
                W[w_idx(k, i), col] = 1
                col += 1
    return {"U": U.tolist(), "V": V.tolist(), "W": W.tolist()}

